              columnar_request.operation_ids = {"COLUMNAR_SOURCE"};
              columnar_request.operation_id = "COLUMNAR_SOURCE";
              columnar_request.relation_uuid = source_input.object_uuid;
              columnar_request.row_uuids = std::move(row_uuids);
